'use strict';
const CARD_POOL=[
['summer','SR','后藤一里','夏日启动失败','official/ep09-1.jpg'],['twister','SR','后藤一里','人类形态维持困难','official/ep07-2.jpg'],['festival','SSR','结束乐队','文化祭作战开始','official/ep11-4.jpg'],['ryostage','SSR','山田凉','贝斯手的余裕','official/ep11-2.jpg'],['room','SR','后藤一里','欢迎来到秘密基地','official/ep07-4.jpg'],['smile','SR','广井菊里','大人的生存之道','official/ep06-4.jpg'],['camera','SR','喜多郁代','镜头捕获成功','official/ep07-3.jpg'],['train','SR','结束乐队','下北泽以外的世界','official/ep09-4.jpg'],
['drums','SSR','伊地知虹夏','鼓点突破天际','official/ep08-4.jpg'],['bassist','SSR','山田凉','孤高频率','official/ep04-4.jpg'],['blanket','SR','后藤一里','白色结界展开','official/ep08-2.jpg'],['leader','SR','伊地知虹夏','队长的胜利宣言','official/ep04-3.jpg'],['first','SR','后藤一里','后台待机中','official/ep01-1.jpg'],['meeting','SR','结束乐队','命运开始转动','official/ep01-2.jpg'],['hallway','SR','喜多郁代','走廊里的发光体','official/ep01-3.jpg'],['alone','R','后藤一里','下北泽潜行任务','official/ep01-4.jpg'],
['hitori','R','后藤一里','社交系统未响应','official/ep02-1.jpg'],['nijika','R','伊地知虹夏','结束乐队的常识人','official/ep03-3.jpg'],['ryo','R','山田凉','余额：危险等级','official/ep03-4.jpg'],['ikuyo','R','喜多郁代','现充光环展开','official/ep11-3.jpg'],
['frame','SR','结束乐队','宣传照作战','b-ep04.jpg'],['guitar','SR','喜多郁代','蓝色六弦的秘密','b-ep04b.jpg'],['voice','SR','喜多郁代','聚光灯锁定','b-ep08.jpg'],['notebook','SR','结束乐队','作战会议进行中','b-ep08b.jpg'],
['sunset','SSR','结束乐队','下北泽的归途','official/ph_all_1.jpg'],['hero','SSR','后藤一里','吉他英雄，启动','official/ph_hitori_1.jpg'],['shine','SSR','喜多郁代','闪耀超出安全阈值','official/ph_ikuyo_1.jpg']
].map(([id,rarity,name,title,img])=>({id,rarity,name,title,img:'assets/art/'+img}));
const validGacha=g=>g&&Number.isInteger(g.pity)&&g.pity>=0&&g.pity<30&&Number.isInteger(g.total)&&g.total>=0&&g.cards&&typeof g.cards==='object'&&!Array.isArray(g.cards)&&Object.entries(g.cards).every(([id,n])=>CARD_POOL.some(c=>c.id===id)&&Number.isInteger(n)&&n>0);
if(!validGacha(state.gacha))state.gacha={pity:0,total:0,cards:{}};
// Each ten-pull guarantees an SR-or-higher card. SSR resets the shared 30-pull pity.
function drawCards(g,count,rng=Math.random){let result=[],high=false;const used=new Set();for(let i=0;i<count;i++){const r=rng();let rarity=g.pity>=29?'SSR':r<.03?'SSR':r<.20?'SR':'R';if(count===10&&i===9&&!high&&rarity==='R')rarity='SR';let pool=CARD_POOL.filter(c=>c.rarity===rarity&&!used.has(c.id));if(!pool.length){rarity=rarity==='R'?'SR':'SSR';pool=CARD_POOL.filter(c=>c.rarity===rarity&&!used.has(c.id))}if(!pool.length)pool=CARD_POOL.filter(c=>!used.has(c.id));const card=pool[Math.min(pool.length-1,Math.floor(rng()*pool.length))];rarity=card.rarity;used.add(card.id);if(rarity!=='R')high=true;const isNew=!g.cards[card.id];g.cards[card.id]=(g.cards[card.id]||0)+1;g.pity=rarity==='SSR'?0:g.pity+1;g.total++;result.push({...card,isNew})}return result}
function showCard(c){showModal(c.title,`<img class="full-card-image" src="${c.img}" alt="${c.name} · ${c.title}"><p>${c.rarity} · ${c.name} · ${state.gacha.cards[c.id]?'已收藏 '+state.gacha.cards[c.id]+' 张':'尚未获得'}</p><a class="text-button" href="${c.img}" target="_blank" rel="noopener">查看原始图片 ↗</a>`)}
function cardHTML(c,extra=''){return `<span class="card-art"><img src="${c.img}" alt="${c.name} · ${c.title}" loading="lazy"></span><span class="card-rarity">${c.rarity} <small>${extra}</small></span><b>${c.title}</b><small>${c.name}</small>`}
function renderGacha(){const g=state.gacha;$('#gachaCount').textContent=`图鉴 ${Object.keys(g.cards).length} / ${CARD_POOL.length} · 累计 ${g.total} 抽`;$('#gachaPity').textContent=`SSR 最迟再 ${30-g.pity} 抽出现`;$('#cardCollection').innerHTML=CARD_POOL.map(c=>`<button class="collect-card rarity-${c.rarity} ${g.cards[c.id]?'':'unowned'}" data-card="${c.id}">${cardHTML(c,g.cards[c.id]?'×'+g.cards[c.id]:'未获得')}</button>`).join('');$$('[data-card]').forEach(b=>b.onclick=()=>showCard(CARD_POOL.find(c=>c.id===b.dataset.card)))}
function pull(count){const results=drawCards(state.gacha,count);persist();renderGacha();$('#pullResults').innerHTML=results.map((c,i)=>`<button class="collect-card reveal-card rarity-${c.rarity}" style="--delay:${i*65}ms" aria-label="翻开第 ${i+1} 张卡"><span class="card-back"><img src="assets/art/official/kessoku-logo.svg" alt="结束乐队 Logo"><small>点击揭晓</small></span><span class="card-front">${cardHTML(c,c.isNew?'NEW':'重复收藏')}</span></button>`).join('');$('#pullStatus').textContent=`${count===10?'十连':'单抽'}已入册 · 翻开后再点查看完整图`;$$('.reveal-card').forEach((b,i)=>b.onclick=()=>{if(b.classList.contains('revealed')){showCard(results[i]);return}b.classList.add('revealed');b.setAttribute('aria-label',b.querySelector('.card-front').textContent)});$('#revealAll').hidden=false;$('#pullResults').scrollIntoView({block:'nearest',behavior:state.reduced?'instant':'smooth'})}
$('#pullOne').onclick=()=>pull(1);$('#pullTen').onclick=()=>pull(10);$('#revealAll').onclick=()=>$$('.reveal-card').forEach(b=>{b.classList.add('revealed');b.setAttribute('aria-label',b.querySelector('.card-front').textContent)});$('#gachaRules').onclick=()=>showModal('虹夏的抽卡说明书','<p>不消耗门票。初始稀有度概率：SSR 3%、SR 17%、R 80%；本次未出现的同稀有度卡等概率。</p><p>每次十连至少一张 SR 或 SSR。如果前九张全是 R 且第十张也是 R，第十张升级为 SR。连续 29 抽未出 SSR，下一抽必为 SSR；抽到 SSR 后重新计数，单抽与十连共享。</p><p>同一次十连不重复；若 R 或 SR 已抽完，则升级补位；SSR 已抽完时从本批剩余卡中抽取。因此十连实际分布不同于初始概率。跨批次重复卡保留数量。所有剧情、音乐独立开放。卡名是同人创作，图片来自官方公开素材；进度保存在当前浏览器，可在设置中导出。</p>');renderGacha();
